window.products.push({"id":404056,"name":"Star Wars 7-Quart Digital Slow Cooker with Sound","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/81azbOphLML._AC_SL1500_.jpg","description":"Prepare a meal worthy of the galaxy's finest. Programmed with Star Wars sound effects this slow cooker adds a whole new element to creating your favorite galactic recipes. With the digital control the cooking time and temperature can be customized for any meal. After cooking the slow cooker automatically shifts to a keep warm and after 6 hours shuts off. The 7 quart capacity is ideal for homemade favorites like roast chicken, beef tenderloin, pulled pork, hearty stews and even desserts.","images":["https://m.media-amazon.com/images/I/81azbOphLML._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"STAR WARS","source_asin":"B08MT2H9Y5","category_path":"Home & Kitchen"},"sku":"BM-404056","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08MT2H9Y5","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08MT2H9Y5","price_pending":true,"merchant_ready":false});
